async function runScheduledSystemJobs(env: Env, firedAt: Date, ctx: ExecutionContext): Promise<void> {
  if (matchesCron("*/5 * * * *", firedAt)) {
    await runPeriodicScan(env);
  }
  if (matchesCron("0 * * * *", firedAt)) {
    await cleanupStaleSessions(env);
    try { const { pruneRateLimits } = await import("./rateLimit"); await pruneRateLimits(env); } catch {}
    const { runIntelScans } = await import("./intel/jobs");
    await runIntelScans(env, ctx);
  }
  if (matchesCron("0 8 * * 1", firedAt)) {
    const { runWeeklyBriefs } = await import("./intel/jobs");
    await runWeeklyBriefs(env);
  }
  if (matchesCron("0 2 * * *", firedAt)) {
    const { runBattlecardStaleCheck } = await import("./intel/jobs");
    const result = await runBattlecardStaleCheck(env);
    if (result.refreshed > 0) console.log(`Battlecard stale check: ${result.refreshed}/${result.checked} refreshed`);
  }
}

async function runScheduledUserJobs(env: Env, firedAt: Date): Promise<void> {
  const { results } = await env.DB.prepare(
    "SELECT id, cron, name, user_id, chat_id, channel FROM cron_schedules"
  ).all<{ id: string; cron: string; name: string | null; user_id: string; chat_id: string; channel: string }>();

  for (const schedule of results || []) {
    if (!matchesCron(schedule.cron, firedAt)) continue;
    if (!schedule.user_id || !schedule.chat_id) continue;
    try {
      await runSingleScan(env, {
        target: schedule.name || "Periodic market scan",
        userId: schedule.user_id,
        chatId: schedule.chat_id,
        channel: schedule.channel || "telegram",
      });
    } catch (err) {
      console.error(`User scan failed for schedule ${schedule.id}:`, err);
    }
  }
}

function matchStep(sub: string, value: number): boolean {
  const step = parseInt(sub.substring(2), 10);
  return !isNaN(step) && value % step === 0;
}

function matchRange(sub: string, value: number): boolean {
  const [startStr, endStr] = sub.split("-");
  const start = parseInt(startStr, 10);
  const end = parseInt(endStr, 10);
  return !isNaN(start) && !isNaN(end) && value >= start && value <= end;
}

function matchExact(sub: string, value: number): boolean {
  const exact = parseInt(sub, 10);
  return !isNaN(exact) && value === exact;
}

function matchCronSubField(sub: string, value: number): boolean {
  if (sub === "*") return true;
  if (sub.startsWith("*/")) return matchStep(sub, value);
  if (sub.includes("-")) return matchRange(sub, value);
  return matchExact(sub, value);
}

function matchCronField(field: string, value: number): boolean {
  if (field === "*") return true;
  return field.split(",").some((sub) => matchCronSubField(sub, value));
}

function matchesCron(expression: string, date: Date): boolean {
  const parts = expression.trim().split(/\s+/);
  if (parts.length !== 5) return false;

  const values = [
    date.getMinutes(),
    date.getHours(),
    date.getDate(),
    date.getMonth() + 1,
    date.getDay(),
  ];

  for (let i = 0; i < 5; i++) {
    if (!matchCronField(parts[i], values[i])) return false;
  }
  return true;
}

