    !u.includes("yahoo.com") && !u.includes("duckduckgo") && !u.includes("wikipedia.org/wiki/") && !u.includes("youtube.com")
  ).slice(0, maxArticles);
}

async function fetchResearchArticles(urls: string[], fetchTimeout: number): Promise<string[]> {
  const articlePromises = urls.map(async (url) => {
    try {
      const readerUrl = `https://md.auxlo.xyz/${url}`;
      const response = await fetchWithTimeout(readerUrl, {
        headers: { "User-Agent": "Mozilla/5.0 (compatible; AuxloNeo/1.0)", "Accept": "text/plain" },
        redirect: "follow",
      }, fetchTimeout);
      if (response.ok) {
        let text = await response.text();
        if (text.length > 4000) text = text.slice(0, 4000) + "\n[truncated]";
        return `--- Source: ${url} ---\n${text}`;
      }
    } catch {}
    return null;
  });
  const articleOut = await Promise.all(articlePromises);
  return articleOut.filter((a): a is string => a !== null);
}

async function fetchResearchXPosts(topic: string, fetchTimeout: number): Promise<string[]> {
  const xQuery = encodeURIComponent(topic);
  const xUrl = `https://api.vxtwitter.com/Twitter/search/${xQuery}`;
  try {
    const response = await fetchWithTimeout(xUrl, {
      headers: { "User-Agent": "Mozilla/5.0 (compatible; AuxloNeo/1.0)" },
    }, fetchTimeout);
    if (response.ok) {
      const data: any = await response.json();
      if (data.tweets && Array.isArray(data.tweets)) {
        return data.tweets.slice(0, 5).map((tweet: any) =>
          `@${tweet.user_screen_name}: ${tweet.text} (${tweet.likes || 0} likes)`
        );
      }
    }
  } catch {}
  return [];
}

async function toolResearchTopic(
  env: Env,
  topic: string,
  depth: string,
  ctx?: ToolContext
): Promise<ToolResult> {
  const maxSearches = depth === "deep" ? 2 : 1;
  const maxArticles = depth === "deep" ? 3 : depth === "standard" ? 2 : 1;
  const fetchTimeout = 8000;

  const searchResults = await fetchResearchSearchResults(topic, maxSearches, fetchTimeout);
  const uniqueUrls = extractUniqueUrls(searchResults, maxArticles);
  const articleContents = await fetchResearchArticles(uniqueUrls, fetchTimeout);
  const xPosts = depth !== "quick" ? await fetchResearchXPosts(topic, fetchTimeout) : [];

  const report: string[] = [`# Research: ${topic}\n`];

  if (searchResults.length > 0) {
    report.push(`## Web Search Results\n${searchResults.join("\n\n---\n\n")}\n`);
  }
  if (articleContents.length > 0) {
    report.push(`## Detailed Articles\n${articleContents.join("\n\n")}\n`);
  }
  if (xPosts.length > 0) {
    report.push(`## X/Twitter Discussion\n${xPosts.join("\n")}\n`);
  }

  if (report.length === 1) {
    return { content: `No results found for "${topic}". Try a different query.` };
  }

  const fullReport = report.join("\n");
  return { content: fullReport.length > 15000 ? fullReport.slice(0, 15000) + "\n\n[truncated]" : fullReport };
}

